package com.rekluzlabs.makokolorize.ui.screensimport android.net.Uriimport androidx.activity.compose.rememberLauncherForActivityResultimport androidx.activity.result.PickVisualMediaRequestimport androidx.activity.result.contract.ActivityResultContractsimport androidx.compose.foundation.Imageimport androidx.compose.foundation.layout.Arrangementimport androidx.compose.foundation.layout.Columnimport androidx.compose.foundation.layout.Rowimport androidx.compose.foundation.layout.Spacerimport androidx.compose.foundation.layout.aspectRatioimport androidx.compose.foundation.layout.fillMaxSizeimport androidx.compose.foundation.layout.fillMaxWidthimport androidx.compose.foundation.layout.heightimport androidx.compose.foundation.layout.paddingimport androidx.compose.foundation.layout.sizeimport androidx.compose.foundation.shape.RoundedCornerShapeimport androidx.compose.material.icons.Iconsimport androidx.compose.material.icons.filled.Settingsimport androidx.compose.material3.Buttonimport androidx.compose.material3.ExperimentalMaterial3Apiimport androidx.compose.material3.Iconimport androidx.compose.material3.IconButtonimport androidx.compose.material3.OutlinedButtonimport androidx.compose.material3.Scaffoldimport androidx.compose.material3.Textimport androidx.compose.material3.TopAppBarimport androidx.compose.runtime.Composableimport androidx.compose.runtime.getValueimport androidx.compose.runtime.mutableStateOfimport androidx.compose.runtime.rememberimport androidx.compose.runtime.setValueimport androidx.compose.ui.Alignmentimport androidx.compose.ui.Modifierimport androidx.compose.ui.draw.clipimport androidx.compose.ui.layout.ContentScaleimport androidx.compose.ui.res.painterResourceimport androidx.compose.ui.text.font.FontWeightimport androidx.compose.ui.unit.dpimport androidx.compose.ui.unit.spimport coil.compose.rememberAsyncImagePainterimport com.rekluzlabs.makokolorize.R@OptIn(ExperimentalMaterial3Api::class)@Composablefun PickerScreen(    onImageSelected: (Uri) -> Unit,    onNavigateToSettings: () -> Unit) {    var selectedUri by remember { mutableStateOf<Uri?>(null) }    val picker = rememberLauncherForActivityResult(        contract = ActivityResultContracts.PickVisualMedia()    ) { uri: Uri? ->        uri?.let { selectedUri = it }    }    Scaffold(        topBar = {            TopAppBar(                title = { Text("makokolorize") },                actions = {                    IconButton(onClick = onNavigateToSettings) {                        Icon(                            Icons.Default.Settings,                            contentDescription = "Settings"                        )                    }                }            )        }    ) { padding ->        Column(            modifier = Modifier                .fillMaxSize()                .padding(padding)                .padding(24.dp),            horizontalAlignment = Alignment.CenterHorizontally,            verticalArrangement = Arrangement.Center        ) {            Image(                painter = painterResource(id = R.mipmap.ic_launcher_foreground),                contentDescription = "App Logo",                modifier = Modifier                    .size(120.dp)                    .clip(RoundedCornerShape(24.dp))            )            Spacer(modifier = Modifier.height(16.dp))            Text(                text = "makokolorize",                fontSize = 24.sp,                fontWeight = FontWeight.Bold            )            Spacer(modifier = Modifier.height(32.dp))            if (selectedUri == null) {                Button(onClick = {                    picker.launch(PickVisualMediaRequest(ActivityResultContracts.PickVisualMedia.ImageOnly))                }) {                    Text("Select Photo")                }            } else {                Image(                    painter = rememberAsyncImagePainter(selectedUri),                    contentDescription = "Selected photo",                    modifier = Modifier                        .fillMaxWidth()                        .aspectRatio(1f)                        .clip(RoundedCornerShape(12.dp)),                    contentScale = ContentScale.Fit                )                Spacer(modifier = Modifier.height(24.dp))                Row(horizontalArrangement = Arrangement.spacedBy(16.dp)) {                    OutlinedButton(onClick = {                        selectedUri = null                    }) {                        Text("Back")                    }                    Button(onClick = {                        selectedUri?.let { onImageSelected(it) }                    }) {                        Text("Confirm")                    }                }            }        }    }}